define("mod_videoguide/videoguide",["core/ajax","core/notification","core/config"],function(Ajax,Notification,Config){var init=function(){document.addEventListener("click",function(e){var btn=e.target.closest(".toggle-view-btn");if(!btn)return;e.preventDefault();var videoid=btn.dataset.videoid;var row=btn.closest("tr");Ajax.call([{methodname:"mod_videoguide_toggle_viewed",args:{videoid:videoid,sesskey:Config.sesskey}}])[0].done(function(response){if(response.viewed){btn.classList.remove("btn-outline-secondary");btn.classList.add("btn-success");btn.querySelector("i").classList.remove("fa-circle-o");btn.querySelector("i").classList.add("fa-check-circle");row.classList.add("table-success","viewed-row")}else{btn.classList.remove("btn-success");btn.classList.add("btn-outline-secondary");btn.querySelector("i").classList.remove("fa-check-circle");btn.querySelector("i").classList.add("fa-circle-o");row.classList.remove("table-success","viewed-row")}location.reload()}).fail(function(error){Notification.exception(error)})});var rows=document.querySelectorAll(".videoguide-table tbody tr");for(var i=0;i<rows.length;i++){rows[i].classList.add("fade-in-row")}};return{init:init}});